 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != 0]
    if not pts:
        return [row[:] for row in grid]
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    box = [row[c0:c1+1] for row in grid[r0:r1+1]]
    colors = Counter(v for row in box for v in row if v != 0)
    frame = colors.most_common(1)[0][0]
    inside = next(v for v, _ in colors.most_common() if v != frame)
    bh, bw = len(box), len(box[0])
    t = 0
    while t < min(bh, bw) // 2 and (
        all(v == frame for v in box[t]) and
        all(v == frame for v in box[bh-1-t]) and
        all(box[r][t] == frame and box[r][bw-1-t] == frame for r in range(bh))
    ):
        t += 1
    out = [row[:] for row in grid]
    for r in range(max(0, r0-t), min(h, r1+t+1)):
        for c in range(max(0, c0-t), min(w, c1+t+1)):
            out[r][c] = inside
    for r in range(r0, r1+1):
        for c in range(c0, c1+1):
            out[r][c] = grid[r][c]
    return out
